--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` varchar(50) NOT NULL,
  `branch_id` int NOT NULL,
  `daily_order_number` int NOT NULL,
  `type` varchar(50) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `kitchen_status` varchar(20) DEFAULT 'pending',
  `subtotal` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tax` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `manual_discount` decimal(10,2) DEFAULT '0.00',
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime DEFAULT NULL,
  `ready_at` datetime DEFAULT NULL,
  `waiter_id` int DEFAULT NULL,
  `chef` varchar(100) DEFAULT NULL,
  `table_id` int DEFAULT NULL,
  `customer_id` int DEFAULT NULL,
  `delivery_address_id` varchar(50) DEFAULT NULL,
  `amount_paid` decimal(10,2) DEFAULT '0.00',
  `change_given` decimal(10,2) DEFAULT '0.00',
  `created_by_user_id` int DEFAULT NULL,
  `delivery_driver_id` int DEFAULT NULL,
  `delivery_status` varchar(50) DEFAULT 'pending',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_orders_creator` (`created_by_user_id`),
  CONSTRAINT `fk_orders_creator` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
